options.afterRender:
const root = context.element.querySelector('#ec2-controller');
if (!root) return;

if (root.dataset.initialized === 'true') return;
root.dataset.initialized = 'true';

const input = root.querySelector('#ec2-count');

function clamp(v) {
  v = parseInt(v);
  if (isNaN(v) || v < 0) v = 0;
  if (v > 8) v = 8;
  return v;
}
function changeCount(delta) {
  const v = parseInt(input.value) || 0;
  input.value = clamp(v + delta);
}

input.addEventListener('input', () => {
  input.value = input.value.replace(/[^0-9]/g, '');
  if (input.value !== '' && parseInt(input.value) > 8) input.value = 8;
});
input.addEventListener('blur', () => { input.value = clamp(input.value); });
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter')     { e.target.blur(); }
  if (e.key === 'ArrowUp')   { e.preventDefault(); changeCount(1); }
  if (e.key === 'ArrowDown') { e.preventDefault(); changeCount(-1); }
});

root.querySelectorAll('.arrow-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    changeCount(parseInt(btn.dataset.delta));
  });
});

// ✅ action에 따라 엔드포인트 분기
function callApi(action) {
  input.value = clamp(input.value);
  const count = parseInt(input.value) || 0;
  if (count === 0) {
    alert('EC2 수를 1 이상으로 입력하세요');
    return;
  }

  // action: "scale-out" → /api/scale-out
  // action: "scale-in"  → /api/scale-in
  const endpoint = action; // "scale-out" or "scale-in"

  fetch(`http://${window.location.hostname}:8001/api/${endpoint}`, {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      action: action,
      delta: count,
      user: 'grafana'
    })
  })
  .then(r => {
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    return r.json();
  })
  .then(d => {
    const label = action === 'scale-out' ? '🟢 Scale-Out' : '🔴 Scale-In';
    alert(`✅ ${label}: ${count}대 요청 완료\n${d.message || ''}`);
  })
  .catch(e => alert(`❌ ${e.message}`));
}

function callRollback() {
  if (!confirm('정말 롤백하시겠습니까?')) return;
  fetch(`http://${window.location.hostname}:8001/api/rollback`, {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({action: 'rollback', user: 'grafana'})
  })
  .then(r => r.json())
  .then(d => alert('🔄 Rollback 실행됨'))
  .catch(e => alert(`❌ ${e.message}`));
}

root.querySelectorAll('.action-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const action = btn.dataset.action;
    if (action === 'rollback') callRollback();
    else callApi(action);   // 'scale-out' 또는 'scale-in'
  });
});

