(function initScalingController() {

  // ============ 0. 중복 root 완전 제거 ============

  const allRoots = document.querySelectorAll('#scaling-duration-controller');

  if (allRoots.length === 0) return;



  for (let i = 0; i < allRoots.length - 1; i++) {

    allRoots[i].remove();

  }

  const root = document.querySelector('#scaling-duration-controller');

  if (!root) return;



  // ============ 0-1. 중복 초기화 방지 ============

  if (root.dataset.initialized === 'true') return;

  root.dataset.initialized = 'true';



  // ============ ✅ FastAPI 설정 ============

  const API_BASE = `http://${window.location.hostname}:8001/api`;



  // ============ 1. 요소 가져오기 ============

  const currentTimeEl = root.querySelector('#currentTime');

  const reserveInput = root.querySelector('#reserve-input');

  const durationInput = root.querySelector('#duration-input');

  const capSlider = root.querySelector('#capacity-slider');

  const capValue = root.querySelector('#capValue');

  const applyBtn = root.querySelector('#apply-btn');

  const activeList = root.querySelector('#activeList');



  if (!applyBtn || !durationInput || !capSlider || !activeList) return;



  // ============ 2. CURRENT TIME ============

  function updateCurrentTime() {

    const now = new Date();

    const hh = String(now.getHours()).padStart(2, '0');

    const mm = String(now.getMinutes()).padStart(2, '0');

    const ss = String(now.getSeconds()).padStart(2, '0');

    if (currentTimeEl) currentTimeEl.textContent = hh + ':' + mm + ':' + ss;

  }

  updateCurrentTime();



  if (window.__scalingTimer) {

    clearInterval(window.__scalingTimer);

    window.__scalingTimer = null;

  }

  window.__scalingTimer = setInterval(updateCurrentTime, 1000);



  // ============ 3. RESERVE TIME ============

  function toLocalDatetimeValue(date) {

    const yyyy = date.getFullYear();

    const mm = String(date.getMonth() + 1).padStart(2, '0');

    const dd = String(date.getDate()).padStart(2, '0');

    const hh = String(date.getHours()).padStart(2, '0');

    const mi = String(date.getMinutes()).padStart(2, '0');

    return yyyy + '-' + mm + '-' + dd + 'T' + hh + ':' + mi;

  }

  if (reserveInput && !reserveInput.value) {

    reserveInput.value = toLocalDatetimeValue(new Date());

  }



  // ============ 4. DURATION ============

  const durButtons = root.querySelectorAll('.dur-btn');



  function setActiveDurBtn(value) {

    durButtons.forEach(function (b) {

      b.classList.toggle('active', parseInt(b.dataset.min, 10) === value);

    });

  }



  durButtons.forEach(function (btn) {

    const newBtn = btn.cloneNode(true);

    btn.parentNode.replaceChild(newBtn, btn);

    newBtn.addEventListener('click', function () {

      const min = parseInt(newBtn.dataset.min, 10);

      durationInput.value = min;

      setActiveDurBtn(min);

    });

  });



  root.querySelectorAll('.arrow-btn').forEach(function (btn) {

    const newBtn = btn.cloneNode(true);

    btn.parentNode.replaceChild(newBtn, btn);

    newBtn.addEventListener('click', function () {

      const delta = parseInt(newBtn.dataset.delta, 10);

      let v = parseInt(durationInput.value, 10) || 0;

      v = Math.max(1, Math.min(240, v + delta));

      durationInput.value = v;

      setActiveDurBtn(v);

    });

  });



  durationInput.addEventListener('input', function () {

    setActiveDurBtn(parseInt(durationInput.value, 10));

  });

  setActiveDurBtn(parseInt(durationInput.value, 10));



  // ============ 5. CAPACITY ============

  capSlider.addEventListener('input', function () {

    capValue.textContent = capSlider.value;

  });



  // ============ ✅ FastAPI 호출 함수 ============

  // 예약 등록 (Apply 시 즉시 호출)

  function registerReserveScale(scheduleId, reserveAt, capacity, duration) {

    return fetch(`${API_BASE}/reserve_scale`, {

      method: 'POST',

      headers: { 'Content-Type': 'application/json' },

      body: JSON.stringify({

        schedule_id: scheduleId,

        reserve_at: reserveAt,

        capacity: capacity,

        duration: duration,

        user: 'grafana'

      })

    })

      .then(r => {

        if (!r.ok) throw new Error('서버 응답 오류: ' + r.status);

        return r.json();

      });

  }



  // 예약 취소 (X 버튼 클릭 시)

  function cancelReserveScale(scheduleId) {

    return fetch(`${API_BASE}/reserve_scale/${scheduleId}`, {

      method: 'DELETE'

    })

      .then(r => {

        if (!r.ok) throw new Error('서버 응답 오류: ' + r.status);

        return r.json();

      });

  }



  // ============ 6. ACTIVE SCHEDULE ============

  function formatReserveDisplay(dtStr) {

    if (!dtStr) return '-';

    const d = new Date(dtStr);

    if (isNaN(d.getTime())) return dtStr;

    const yyyy = d.getFullYear();

    const mm = String(d.getMonth() + 1).padStart(2, '0');

    const dd = String(d.getDate()).padStart(2, '0');

    const hh = String(d.getHours()).padStart(2, '0');

    const mi = String(d.getMinutes()).padStart(2, '0');

    return yyyy + '-' + mm + '-' + dd + ' ' + hh + ':' + mi;

  }



  if (!window.__schedules) window.__schedules = [];

  const schedules = window.__schedules;



  function renderList() {

    activeList.innerHTML = '';

    if (schedules.length === 0) {

      const empty = document.createElement('div');

      empty.className = 'empty';

      empty.textContent = '활성화된 스케일링 없음';

      activeList.appendChild(empty);

      return;

    }

    schedules.forEach(function (s) {

      const item = document.createElement('div');

      item.className = 'item';



      const info = document.createElement('div');

      info.className = 'item-info';



      const title = document.createElement('div');

      title.className = 'item-title';

      title.textContent = '예약시간: ' + formatReserveDisplay(s.reserveAt);



      const sub = document.createElement('div');

      sub.className = 'sub';

      sub.textContent = 'Duration: ' + s.duration + '분 · Target Capacity: ' + s.capacity + ' instances';



      info.appendChild(title);

      info.appendChild(sub);



      const removeBtn = document.createElement('button');

      removeBtn.className = 'remove-btn';

      removeBtn.type = 'button';

      removeBtn.textContent = '✕';

      removeBtn.addEventListener('click', async function () {

        // ✅ FastAPI에 취소 요청 전송

        try {

          await cancelReserveScale(s.id);

          console.log('✅ 예약 취소 완료:', s.id);

        } catch (err) {

          console.error('❌ 예약 취소 실패:', err);

          // 취소 실패해도 일단 목록에서는 제거 (이미 실행됐을 수 있음)

        }



        const idx = schedules.findIndex(function (x) { return x.id === s.id; });

        if (idx > -1) {

          schedules.splice(idx, 1);

          renderList();

        }

      });



      item.appendChild(info);

      item.appendChild(removeBtn);

      activeList.appendChild(item);

    });

  }



  // ============ 7. Apply (cloneNode로 기존 핸들러 완전 제거) ============

  const newApplyBtn = applyBtn.cloneNode(true);

  applyBtn.parentNode.replaceChild(newApplyBtn, applyBtn);



  let isProcessing = false;



  newApplyBtn.addEventListener('click', async function (e) {

    e.preventDefault();

    e.stopPropagation();



    if (isProcessing) return;



    const now = Date.now();

    if (window.__lastApplyTime && now - window.__lastApplyTime < 300) {

      return;

    }

    window.__lastApplyTime = now;



    isProcessing = true;

    newApplyBtn.disabled = true;



    try {

      const reserveAt = reserveInput.value;

      const duration = parseInt(durationInput.value, 10);

      const capacity = parseInt(capSlider.value, 10);



      if (!reserveAt) {

        alert('예약 시간을 선택해주세요.');

        return;

      }

      if (!duration || duration < 1) {

        alert('Duration을 올바르게 입력해주세요.');

        return;

      }

      if (new Date(reserveAt).getTime() <= Date.now()) {

        alert('예약 시간은 현재 시간 이후여야 합니다.');

        return;

      }



      const newSchedule = {

        id: Date.now() + '-' + Math.random().toString(36).slice(2, 7),

        reserveAt: reserveAt,

        duration: duration,

        capacity: capacity

      };



      // ✅ FastAPI에 예약 등록 요청

      try {

        await registerReserveScale(

          newSchedule.id,

          newSchedule.reserveAt,

          newSchedule.capacity,

          newSchedule.duration

        );

        console.log('✅ 예약 등록 완료:', newSchedule.id);

      } catch (err) {

        console.error('❌ 예약 등록 실패:', err);

        alert('예약 등록에 실패했습니다: ' + err.message);

        return;

      }



      schedules.push(newSchedule);

      renderList();

    } finally {

      setTimeout(function () {

        isProcessing = false;

        newApplyBtn.disabled = false;

      }, 300);

    }

  });



  // ============ ✅ 8. 서버에서 예약 목록 동기화 ============
  async function loadSchedulesFromServer() {
    try {
      const res = await fetch(`${API_BASE}/reserve_scale`);
      if (!res.ok) throw new Error('서버 응답 오류: ' + res.status);
      const data = await res.json();

      schedules.length = 0;
      (data.schedules || []).forEach(s => {
        schedules.push({
          id: s.schedule_id,
          reserveAt: s.reserve_at,
          capacity: s.capacity,
          duration: s.duration
        });
      });

      renderList();
      console.log(`✅ 서버에서 예약 ${schedules.length}개 불러옴`);
    } catch (err) {
      console.error('❌ 예약 목록 불러오기 실패:', err);
      renderList();
    }
  }

  loadSchedulesFromServer();   // ← renderList() 대신 이거 호출

})();

